def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    import datetime
    import pytz

    try:
        if not isinstance(nanoseconds, int):
            raise ValueError("nanoseconds must be an integer")

        if tz is None:
            tz = pytz.utc
        elif not isinstance(tz, datetime.tzinfo):
            raise ValueError("tz must be an instance of datetime.tzinfo")

        seconds = nanoseconds // 1_000_000_000
        nanos = nanoseconds % 1_000_000_000
        dt = datetime.datetime(1970, 1, 1, tzinfo=tz) + datetime.timedelta(seconds=seconds, microseconds=nanos // 1000)
        return dt.time()

    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timezone, timedelta

    try:
        nanoseconds = int(nanoseconds)
    except ValueError:
        raise ValueError("nanoseconds must be an integer")

    seconds = nanoseconds // 1_000_000_000
    nanos = nanoseconds % 1_000_000_000

    # Assume the nanoseconds are since the epoch
    if tz is None:
        dt = datetime.fromtimestamp(seconds, tz=timezone.utc) + timedelta(milliseconds=nanos / 1_000_000)
    else:
        dt = datetime.fromtimestamp(seconds, tz=tz) + timedelta(milliseconds=nanos / 1_000_000)

    return dt.time()

def hydrate_time(nanoseconds, tz=None):
