def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    merged = []
    index_map = {}

    def add_to_merged(obj, index):
        if obj not in index_map:
            index_map[obj] = index
            merged.insert(index, obj)

    for ordering in orderings:
        for index, obj in enumerate(ordering):
            if obj in index_map:
                current_index = index_map[obj]
                if current_index < index:
                    raise ValueError(f"Ordering constraint violated for object {obj}")
            else:
                add_to_merged(obj, index)

    return merged

