    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != len(self.edges) - 1:
        raise ValueError("coord must be a tuple of length one less than the number of edges")

    if weight < 0:
        raise ValueError("weight must be non-negative")

    indices = []
    for i, edge in enumerate(self.edges):
        idx = np.searchsorted(edge, coord[i], side='right') - 1
        if idx < 0 or idx >= len(edge) - 1:
            return  # coordinate is outside the histogram edges
        indices.append(idx)

    self.values[tuple(indices)] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if not all(self.edges[i][0] <= coord[i] < self.edges[i][-1] for i in range(len(coord))):
            return  # Ignore coordinates outside the histogram edges

        bin_indices = [np.searchsorted(self.edges[i], coord[i], side='right') - 1 for i in range(len(coord))]
        self.values[tuple(bin_indices)] += weight

    except (IndexError, TypeError, ValueError) as e:
        print(f"Error filling histogram: {e}")

